/*
 * A100660  Composite numbers whose prime factors have different digital
 *          roots.
 * https://oeis.org/A100660
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  base, easy, nonn
 * Formula:   not stated
 * Range:     u8 n <= 60, u16 n <= 60, u32 n <= 60, u64 n <= 60, u128 n <= 60,
 *            big any n
 * Helpers:   digital_root_uint64
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* 
 * This code implements OEIS sequence A100660: composite numbers whose
 * prime factors have distinct digital roots.
 * The sequence is generated by a straightforward incremental search.
 * a(n) returns the n-th member (a(1) = 6).  No memoization is used;
 * the algorithm recomputes the required number on each call, which
 * is fast enough for n up to about 10 000.
 */

#include <stdbool.h>
#include <stddef.h>
#include <stdlib.h>
#include <stdint.h>
#include "../utils/digital_root_uint64.h"

/* ------------------------------------------------------------ */

/* ------------------------------------------------------------ */
/*  Pre‑computed primes up to 100000                               */
#define PRIME_LIMIT 100000
static uint32_t *prime_list = NULL;
static size_t   prime_cnt  = 0;

static void init_primes(void) {
    if (prime_list != NULL) return;          /* already built */

    size_t prime_cap = PRIME_LIMIT + 1;
    prime_list = (uint32_t*)malloc(prime_cap * sizeof(uint32_t));
    bool *is_composite = (bool*)calloc(PRIME_LIMIT + 1, sizeof(bool));
    if (!prime_list || !is_composite) abort();

    for (uint32_t i = 2; i <= PRIME_LIMIT; ++i) {
        if (!is_composite[i]) {
            prime_list[prime_cnt++] = i;
            if ((uint64_t)i * i <= PRIME_LIMIT) {
                for (uint32_t j = i * i; j <= PRIME_LIMIT; j += i)
                    is_composite[j] = true;
            }
        }
    }
    free(is_composite);
}

/* ------------------------------------------------------------ */
/*  Check whether n (uint64_t) is a member of A100660             */
static bool is_good_candidate(uint64_t v) {
    if (v < 6) return false;          /* minimal composite with distinct roots */

    uint64_t temp = v;
    bool used_root[10] = {0};         /* indices 1‑9 used */
    bool has_factor   = false;

    for (size_t i = 0; i < prime_cnt && (uint64_t)prime_list[i] * prime_list[i] <= temp; ++i) {
        uint32_t p = prime_list[i];
        if (temp % p == 0) {
            int exp = 0;
            while (temp % p == 0) {
                temp /= p;
                ++exp;
            }
            if (exp > 1) return false;            /* repeated factor ⇒ duplicate root */
            uint64_t dr = digital_root_uint64(p);
            if (used_root[dr]) return false;
            used_root[dr] = true;
            has_factor = true;
        }
    }

    if (temp > 1) {    /* remaining prime factor */
        uint64_t dr = digital_root_uint64(temp);
        if (used_root[dr]) return false;
        used_root[dr] = true;
    }

    return has_factor;    /* must be composite (at least one prime factor) */
}

/* ------------------------------------------------------------ */
/*  Main sequence function                                      */
seq_t a(idx_t n) {
    if (n == 0) return (seq_t)0;            /* offset is 1 */

    init_primes();

    uint64_t count  = 0;
    uint64_t cand   = 5;                     /* start just before first term 6 */

    while (count < (uint64_t)n) {
        ++cand;
        if (is_good_candidate(cand))
            ++count;
    }
    return (seq_t)cand;
}
